design:
  schema: fpga-design-agent/project/v1
  name: safe_pwm_audio
  board: nexys_a7_100t
  clocks:
    - {name: clk_sys, source: board, port: CLK100MHZ, mhz: 100}
  resets:
    - {name: rst_sys, domain: clk_sys, polarity: active_low, style: async, from: CPU_RESETN, via: reset_sync}
  shell: {design_id: PWMA, clock: clk_sys, reset: rst_sys}
  modules:
    - name: c12_nexys_pwm_audio_top
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
      params: {CLKS_PER_BIT: 868, TIMEOUT_CYCLES: 10000000, BUILD_STAMP: 0}
      window_base: 0x00
  connections: []
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: CPU_RESETN, dir: in, drive: input, to: rst_sys}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: AUD_PWM, dir: out, drive: open-drain, from: c12_nexys_pwm_audio_top.AUD_PWM}
    - {name: AUD_SD, dir: out, drive: push-pull, from: c12_nexys_pwm_audio_top.AUD_SD}
    - {name: "LED[15:0]", dir: out, drive: push-pull, from: c12_nexys_pwm_audio_top.LED}
  owned: []
  assumptions:
    - {id: A-1, text: "Top-level parameter defaults are not specified.", default: "CLKS_PER_BIT=868, TIMEOUT_CYCLES=10000000, BUILD_STAMP=0", reason: "These are proposed defaults; CLKS_PER_BIT is rounded from 100 MHz / 115200 baud, while the timeout and build stamp have no specified values.", affects: [c12_nexys_pwm_audio_top.contract.parameters], status: open}
    - {id: A-2, text: "Register offsets are not specified.", default: "SAMPLE at 0x00, GAIN at 0x04, SAMPLE_OUT at 0x08, relative to window_base.", reason: "Proposed aligned offsets provide separate word locations within the shell register window.", affects: [c12_nexys_pwm_audio_top.contract.registers, design.modules.c12_nexys_pwm_audio_top.window_base], status: open}
    - {id: A-3, text: "The shell register-window contract does not specify how a write is communicated to the module or how a write can be saturated before the stored register value is read back.", default: "The module's register-window write handling saturates GAIN before storing it and retains SAMPLE between writes.", reason: "This is needed to make a gain write above 8192 store 8192, but the shell-window write mechanism is not detailed in the specification.", affects: [c12_nexys_pwm_audio_top.contract.registers, c12_nexys_pwm_audio_top.module_spec], status: open}

contracts:
  c12_nexys_pwm_audio_top:
    schema: fpga-design-agent/contract/v1
    module: c12_nexys_pwm_audio_top
    hdl_top: c12_nexys_pwm_audio_top
    summary: Holds the audio sample and capped Q15 gain, computes sample_out, and drives the open-drain PWM audio output.
    parameters:
      - {name: CLKS_PER_BIT, default: 868, min: 1, max: 2147483647}
      - {name: TIMEOUT_CYCLES, default: 10000000, min: 1, max: 2147483647}
      - {name: BUILD_STAMP, default: 0, min: 0, max: 2147483647}
    clocks:
      - {name: clk, port: CLK100MHZ, max_mhz: 100}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_low, style: async}
    ports:
      - {name: CLK100MHZ, dir: in}
      - {name: CPU_RESETN, dir: in}
      - {name: rst, dir: in}
      - {name: sample, dir: in, width: 16, clock: clk}
      - {name: gain, dir: in, width: 16, clock: clk}
      - {name: sample_out, dir: out, width: 16, clock: clk, reset_value: 0}
      - {name: AUD_PWM, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: AUD_SD, dir: out, width: 1, clock: clk, reset_value: 1}
      - {name: LED, dir: out, width: 16, clock: clk, reset_value: 0}
    data_formats:
      - {name: audio_sample, format: s16, packing: "signed 16-bit two's-complement audio sample"}
      - {name: q15_gain, format: u16, packing: "unsigned Q15 gain"}
      - {name: processed_sample, format: s16, packing: "signed 16-bit sample_out"}
    interfaces: []
    registers:
      bus: top
      map:
        - {name: SAMPLE, offset: 0x00, access: RW, reset: 0, width: 16, volatile: false, fields: [{name: sample, bits: [15, 0], port: sample}]}
        - {name: GAIN, offset: 0x04, access: RW, reset: 2068, width: 16, volatile: false, fields: [{name: gain, bits: [15, 0], port: gain}]}
        - {name: SAMPLE_OUT, offset: 0x08, access: RO, reset: 0, width: 16, volatile: true, fields: [{name: sample_out, bits: [15, 0], port: sample_out}]}
    latency: []
    throughput: []

module_specs:
  c12_nexys_pwm_audio_top: |
    This single RTL block is the audio output stage. The shell's register window provides
    SAMPLE, GAIN, and SAMPLE_OUT at the proposed offsets. SAMPLE is held between writes;
    GAIN resets to 2068 and is saturated to 8192 on writes above that value. SAMPLE_OUT
    is the combinational signed result floor(sample * gain / 32768).
    The PWM counter is free-running, 10 bits wide, and resets to zero on CPU_RESETN.
    The duty value is 512 + floor(sample_out / 128), latched at counter wrap for the
    following period. AUD_PWM is pulled low at or above the duty value and otherwise
    left high-impedance. AUD_SD is held high and LED is held off.
    The top-level integration also exposes the shell-owned USB-UART pins and forwards
    CLKS_PER_BIT, TIMEOUT_CYCLES, and BUILD_STAMP to the test shell.

requirements:
  - {id: S-1, text: "The block shall accept a signed 16-bit audio sample that is held between sample writes.", proof: [simulation], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-2, text: "The block shall provide an unsigned Q15 gain register that resets to 2068; a gain write above 8192 shall store 8192, and any other gain write shall store the written value.", proof: [simulation], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-3, text: "The signed 16-bit sample_out shall be combinationally computed as floor(sample * gain / 32768).", proof: [simulation, formal], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-4, text: "When CPU_RESETN is asserted, the sample shall be cleared to zero and the gain register shall be set to 2068.", proof: [simulation], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-5, text: "The UART shell shall run at 115200 baud and shall support writing the sample, writing the gain, and reading sample_out.", proof: [simulation, hardware], modules: [c12_nexys_pwm_audio_top, top]}
  - {id: S-6, text: "The PWM shall use a free-running 10-bit counter clocked by CLK100MHZ, producing a 1024-clock period and a carrier frequency of approximately 97.7 kHz.", proof: [simulation, analysis], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-7, text: "The PWM duty value shall be 512 + floor(sample_out / 128), with a nominal value of 512 for silence, and shall be updated once per PWM period.", proof: [simulation, formal], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-8, text: "AUD_PWM shall be open-drain style: it shall be pulled low when the PWM counter is at or above the duty value and otherwise be high-impedance, never actively driven high; each period shall therefore have 1024 minus the duty value low clocks.", proof: [simulation, hardware], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-9, text: "AUD_SD shall be held high.", proof: [simulation, hardware], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-10, text: "The 16-bit LED output shall be held off.", proof: [simulation, hardware], modules: [c12_nexys_pwm_audio_top]}
  - {id: S-11, text: "The top module shall be named c12_nexys_pwm_audio_top and expose AUD_PWM, AUD_SD, CLK100MHZ, CPU_RESETN, the USB-UART pins, LED[15:0], and top-level parameters CLKS_PER_BIT, TIMEOUT_CYCLES, and BUILD_STAMP.", proof: [analysis, hardware], modules: [c12_nexys_pwm_audio_top, top]}
  - {id: S-12, text: "The design shall meet timing at a 100 MHz clock.", proof: [analysis, hardware], modules: [c12_nexys_pwm_audio_top]}

